package org.example.wikimapreader.car;
import android.os.SystemClock;
import org.json.*;
import java.net.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import org.example.wikimapreader.CredentialRepository;
/** Single process-wide serialized transport. Never expose URLs or server error strings. */
public final class WikiApi {
 public static final WikiApi INSTANCE=new WikiApi();
 private final RequestGate gate=new RequestGate();
 private final ExecutorService worker=Executors.newSingleThreadExecutor();
 private final ConcurrentHashMap<String,Job> jobs=new ConcurrentHashMap<>();
 public interface Callback {void done(JSONObject data,String error);}
 static final class Job {volatile boolean cancelled;volatile HttpURLConnection connection;Future<?> future;Callback callback;final java.util.concurrent.atomic.AtomicBoolean delivered=new java.util.concurrent.atomic.AtomicBoolean();void done(JSONObject data,String error){if(delivered.compareAndSet(false,true))callback.done(data,error);}}
 public void cancel(String id){Job j=jobs.remove(id);if(j!=null){j.cancelled=true;j.done(null,"Запрос отменён");if(j.connection!=null)j.connection.disconnect();if(j.future!=null)j.future.cancel(true);}}
 public void request(String id,CredentialRepository keys,String method,JSONObject opts,Callback cb){cancel(id);Job job=new Job();job.callback=cb;jobs.put(id,job);job.future=worker.submit(()->{try{String key=keys.load();if(key==null||key.isEmpty())throw new SafeError("Добавьте ключ API в настройках Auto Dev на телефоне");String url=build(method,key,opts);long at=gate.reserve(SystemClock.elapsedRealtime());while(!job.cancelled&&SystemClock.elapsedRealtime()<at)Thread.sleep(Math.min(200,at-SystemClock.elapsedRealtime()));if(job.cancelled)return;HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();job.connection=c;c.setConnectTimeout(12000);c.setReadTimeout(12000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","WikiReader-AutoDev/0.7.3 (+https://github.com/mnevrov/wikimapia-reader)");int status=c.getResponseCode();if(status==429){gate.backoff(SystemClock.elapsedRealtime(),60000);throw new SafeError("Лимит API: повторите через минуту");}if(status==401||status==403)throw new SafeError("Ключ API отклонён");if(status!=200)throw new IOException("Сеть недоступна. Сохранённые контуры остаются на карте");byte[] bytes=read(c.getInputStream(),4*1024*1024);JSONObject data=new JSONObject(new String(bytes,StandardCharsets.UTF_8));validate(data,method,opts.optLong("id"));if(!job.cancelled)job.done(data,null);
 }catch(InterruptedException e){Thread.currentThread().interrupt();}catch(Exception e){if(!job.cancelled){String msg=e instanceof SafeError?e.getMessage():"Не удалось загрузить данные. Проверьте сеть и ключ на телефоне";if(msg==null||msg.contains("https:")||msg.length()>150)msg="Не удалось загрузить данные. Повторите позже";job.done(null,msg);}}finally{if(job.connection!=null)job.connection.disconnect();jobs.remove(id,job);}});}
 static class SafeError extends IOException {SafeError(String s){super(s);}}
 static byte[] read(InputStream in,int max)throws IOException{try(InputStream s=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=s.read(b))!=-1){if(out.size()+n>max)throw new IOException("Ответ слишком большой");out.write(b,0,n);}return out.toByteArray();}}
 public static String build(String method,String key,JSONObject o)throws Exception {if(key==null||key.trim().isEmpty())throw new IllegalArgumentException("Нужен ключ");Map<String,String> q=new LinkedHashMap<>();q.put("function",method);q.put("key",key.trim());q.put("format","json");q.put("language","ru");q.put("pack","none");switch(method){case "box":double[] b=new double[4];JSONArray a=o.getJSONArray("bbox");if(a.length()!=4)throw new IllegalArgumentException();for(int i=0;i<4;i++)b[i]=a.getDouble(i);Geo.validateBox(b);int page=o.optInt("page",1);if(page<1)throw new IllegalArgumentException();q.put("bbox",b[0]+","+b[1]+","+b[2]+","+b[3]);q.put("coordsby","bbox");q.put("page",String.valueOf(page));q.put("count","50");break;
 case "search":String text=o.getString("query").trim();double lat=o.getDouble("lat"),lon=o.getDouble("lon");if(text.isEmpty()||text.length()>200||!Double.isFinite(lat)||!Double.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180)throw new IllegalArgumentException();q.put("q",text);q.put("lat",String.valueOf(lat));q.put("lon",String.valueOf(lon));q.put("count","20");break;
 case "place.getbyid":long id=o.getLong("id");if(id<1||id>9007199254740991L)throw new IllegalArgumentException();q.put("id",String.valueOf(id));q.put("data_blocks","main,location,geometry,photos,comments");break;default:throw new IllegalArgumentException();}
 StringBuilder s=new StringBuilder("https://api.wikimapia.org/?");for(Map.Entry<String,String> e:q.entrySet())s.append(e.getKey()).append('=').append(URLEncoder.encode(e.getValue(),"UTF-8")).append('&');return s.toString();}
 public static void validate(JSONObject p,String method,long id)throws Exception {if(p.has("debug")||p.has("error")||p.has("error_message")){String e=p.toString().toLowerCase(Locale.ROOT);if(e.matches("(?s).*(quota|limit|wait|too many).*")){INSTANCE.gate.backoff(SystemClock.elapsedRealtime(),60000);throw new SafeError("Лимит API: повторите через минуту");}throw new SafeError("API отклонил запрос. Проверьте ключ на телефоне");}if(method.equals("place.getbyid")){Place place=Place.from(p.optJSONObject("place")!=null?p.getJSONObject("place"):p);if(place.id!=id||place.title.equals("Без названия"))throw new SafeError("API вернул другой объект");}else if(!(p.opt("folder") instanceof JSONArray))throw new SafeError("Некорректный список API");}
}
